            Describe.Lean(DescribeId.Create("pivot"), DeclarationHandle.Create("D5/S3/Observer/Hankel/FiniteHoKalmanBlocks.Pivot"), H("Selected observation and reachability indices"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("A pivot chooses r time/output rows and r time/input columns. Nonsingularity, when required, excludes repetitions automatically."))), DescribeRole.Definition),
