            Describe.Lean(DescribeId.Create("output-block"), DeclarationHandle.Create("D5/S3/Observer/Hankel/FiniteHoKalmanBlocks.outputBlock"), H("Output data block"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("All output coordinates are retained at the selected reachability columns."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("adj-inverse"), DeclarationHandle.Create("D5/S3/Observer/Hankel/FiniteHoKalmanBlocks.adjInverse"), H("Explicit adjugate inverse"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The inverse candidate is computed from the determinant and adjugate. Its correctness requires a nonzero determinant, which the executable search checks."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("adj-inverse-mul"), DeclarationHandle.Create("D5/S3/Observer/Hankel/FiniteHoKalmanBlocks.adjInverse_mul"), H("Left inverse correctness"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Mathlib's adjugate identity proves that the computed candidate is a left inverse."))), DescribeRole.Theorem),
