            Describe.Lean(DescribeId.Create("fitted-b"), DeclarationHandle.Create("D5/S3/Observer/Hankel/FiniteHoKalmanBlocks.fittedB"), H("Computed input map"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The input map is the computed inverse times the input data block."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("fitted-c"), DeclarationHandle.Create("D5/S3/Observer/Hankel/FiniteHoKalmanBlocks.fittedC"), H("Computed output map"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The output data block directly gives the output map in the selected reachable coordinates."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("selected-o"), DeclarationHandle.Create("D5/S3/Observer/Hankel/FiniteHoKalmanBlocks.selectedO"), H("Selected observation matrix"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("This reference-system matrix is used only in the correctness proof. It is not an input to the reconstruction."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("selected-r"), DeclarationHandle.Create("D5/S3/Observer/Hankel/FiniteHoKalmanBlocks.selectedR"), H("Selected reachability matrix"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Its columns define the recovered state coordinates. The algorithm does not need to know the reference system."))), DescribeRole.Definition),
