            Describe.Lean(DescribeId.Create("factorized-exact-recovery"), DeclarationHandle.Create("D5/S3/Observer/Hankel/FiniteHoKalmanBlocks.factorized_exact_recovery"), H("Finite factors imply all-time reproduction"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("A computed inverse supplies two-sided coordinate maps. An induction transports every matrix power, including systems with Jordan blocks."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("finite-samples-exact-recovery"), DeclarationHandle.Create("D5/S3/Observer/Hankel/FiniteHoKalmanBlocks.finite_samples_exact_recovery"), H("Exact finite-sample reconstruction theorem"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Any order-r reference realization matching the finite samples and giving a nonsingular selected minor has exactly the computed all-time behavior. The reference dimension is an explicit model-class hypothesis, not inferred from arbitrary finite data."))), DescribeRole.Theorem)),
